<template>
  <AvatarImageWrapper
    :src="avatarSrc"
    :alt="name || 'User'"
    :fallback="fallback"
    :size="size"
    :fallback-delay-ms="avatarSrc ? 300 : 0"
  />
</template>

<script setup lang="ts">
// Renders a single user's avatar: a public https URL passes through, anything else falls back to
// initials (see resolveAvatarSrc). Extracted as a component because it is rendered inside a v-for —
// each row needs its own instance (e.g. the "start new chat" user picker).
const props = withDefaults(
  defineProps<{
    avatarUrl?: string | null;
    name?: string | null;
    size?: 'base' | 'sm' | 'lg' | 'xs';
  }>(),
  { avatarUrl: null, name: null, size: 'sm' }
);

const avatarSrc = computed(() => resolveAvatarSrc(props.avatarUrl));
const fallback = computed(() => getAvatarFallback(props.name));
</script>
