/**
 * Resolves a renderable avatar `src` from a stored avatar_url value.
 * - public http(s) URL → returned as-is (the browser HTTP-caches the static URL, so the same
 *   user's avatar across the list / header / many messages is one fetch, not per-render)
 * - anything else / null / undefined → '' so AvatarImageWrapper shows the initials fallback.
 *   This is also the transition guard: a stale s3:// value (seen before the migration backfill
 *   completes) never renders as a broken <img> — it falls back to initials.
 */
export function resolveAvatarSrc(url: string | null | undefined): string {
  return url && /^https?:\/\//i.test(url) ? url : '';
}
