import * as Sentry from '@sentry/nuxt';

function getUserContext() {
  const { data: userData } = useAuth();
  if (userData.value?.token) {
    return {
      id: userData.value.token.user.id,
      email: userData.value.token.user.email,
      username: `${userData.value.token.user.first_name} ${userData.value.token.user.last_name}`,
    };
  } else return undefined;
}

export function captureExceptionToSentry(error: unknown) {
  console.error('Captured exception:', error);
  if (error instanceof Error) {
    Sentry.captureException(error, { user: getUserContext() });
  } else {
    Sentry.captureMessage(`Non-error exception captured: ${JSON.stringify(error)}`, { user: getUserContext() });
  }
}
