type ItemWithId = { id?: number | null; [key: string]: any };

export function sortAsc<T extends ItemWithId>(items: T[]) {
  return [...items].sort((a, b) => (a.id ?? 0) - (b.id ?? 0));
}
export function dedupeAsc<T extends ItemWithId>(items: T[]) {
  const map = new Map<number, T>();
  for (const m of items) if (m.id != null) map.set(m.id, m);
  return sortAsc<T>([...map.values()]);
}

type ItemWithCursor = {
  cursor: number | null;
  [key: string]: any;
};

function toTs(v?: string | number | Date | null): number {
  if (!v) return 0;
  if (v instanceof Date) return v.getTime();
  return typeof v === 'string' ? Date.parse(v) : v;
}

export function sortItemsDesc<T extends ItemWithCursor>(items: T[]) {
  return [...items].sort((a, b) => (b.cursor ?? 0) - (a.cursor ?? 0));
}

export function dedupeDescByCursor<T extends ItemWithCursor>(items: T[]) {
  const map = new Map<number, T>();
  for (const m of items) if (m.cursor != null) map.set(m.cursor, m);
  return sortItemsDesc<T>([...map.values()]);
}
